Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();

    Map<TypeVariable<?>, Type> typeVariableMap = getTypeVariableMap(targetType, parameterizedType.getOwnerType());
    if (typeVariableMap == null) {
        return null;
    }

    Class<?>[] result = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;
            Type resolvedType = typeVariableMap.get(typeVariable);
            if (resolvedType != null && resolvedType instanceof ParameterizedType) {
                resolvedType = ((ParameterizedType) resolvedType).getRawType();
            }
            if (resolvedType instanceof Class<?>) {
                result[i] = (Class<?>) resolvedType;
            } else {
                return null; // Could not resolve the type variable
            }
        } else if (typeArgument instanceof ParameterizedType) {
            result[i] = (Class<?>) ((ParameterizedType) typeArgument).getRawType();
        } else if (typeArgument instanceof Class<?>) {
            result[i] = (Class<?>) typeArgument;
        } else {
            return null; // Unsupported type
        }
    }

    return result;
}

Map<TypeVariable<?>, Type> getTypeVariableMap(Class<?> targetType, Type ownerType) {
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    buildTypeVariableMap(targetType, ownerType, typeVariableMap);
    return typeVariableMap;
}

void buildTypeVariableMap(Class<?> targetType, Type ownerType, Map<TypeVariable<?>, Type> typeVariableMap) {
    if (targetType == null) {
        return;
    }

    Type genericSuperclass = targetType.getGenericSuperclass();
    if (genericSuperclass instanceof ParameterizedType) {
        ParameterizedType superParameterizedType = (ParameterizedType) genericSuperclass;
        Class<?> superclass = (Class<?>) superParameterizedType.getRawType();
        Type[] typeParameters = superclass.getTypeParameters();
        Type[] actualTypeArguments = superParameterizedType.getActualTypeArguments();

        for (int i = 0; i < typeParameters.length; i++) {
            typeVariableMap.put((TypeVariable<?>) typeParameters[i], actualTypeArguments[i]);
        }
    } else {
        buildTypeVariableMap((Class<?>) genericSuperclass, ownerType, typeVariableMap);
    }

    for (Type genericInterface : targetType.getGenericInterfaces()) {
        if (genericInterface instanceof ParameterizedType) {
            ParameterizedType interfaceParameterizedType = (ParameterizedType) genericInterface;
            Class<?> interfaceClass = (Class<?>) interfaceParameterizedType.getRawType();
            Type[] typeParameters = interfaceClass.getTypeParameters();
            Type[] actualTypeArguments = interfaceParameterizedType.getActualTypeArguments();

            for (int i = 0; i < typeParameters.length; i++) {
                typeVariableMap.put((TypeVariable<?>) typeParameters[i], actualTypeArguments[i]);
            }
        }
    }
}

