static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Extract year, month, and day from the timeBucket
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket / 100) % 100);
        int day = (int) (timeBucket % 100);

        // Calculate the day of the month that is a multiple of dayStep
        int adjustedDay = ((day - 1) / dayStep) * dayStep + 1;

        // Return the new time bucket
        return year * 10000 + month * 100 + adjustedDay;
    } catch (Exception e) {
        // Handle any unexpected issues gracefully
        System.err.println("Error compressing time bucket: " + e.getMessage());
        return timeBucket; // Return the original time bucket in case of error
    }
}

int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isSurrogate(ch)) {
            // Handle surrogate pairs
            if (i + 1 < index + len && Character.isHighSurrogate(ch) && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4;
                i++; // Skip the low surrogate
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

