void pop(final String descriptor) {
    try {
        // Check if the descriptor is null or empty
        if (descriptor == null || descriptor.isEmpty()) {
            throw new IllegalArgumentException("Descriptor cannot be null or empty");
        }

        // Determine if the descriptor is a method descriptor
        boolean isMethodDescriptor = descriptor.startsWith("(");

        if (isMethodDescriptor) {
            // Find the end of the parameter list in the method descriptor
            int endOfParameters = descriptor.indexOf(')');
            if (endOfParameters == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
            }

            // Extract the parameter types
            String parameters = descriptor.substring(1, endOfParameters);

            // Iterate through each parameter descriptor
            int i = 0;
            while (i < parameters.length()) {
                char typeChar = parameters.charAt(i);

                switch (typeChar) {
                    case 'B': // byte
                    case 'C': // char
                    case 'D': // double
                    case 'F': // float
                    case 'I': // int
                    case 'J': // long
                    case 'S': // short
                    case 'Z': // boolean
                    case 'L': // object reference
                        i++;
                        break;
                    case '[': // array
                        // Skip the array descriptor
                        do {
                            typeChar = parameters.charAt(i++);
                        } while (typeChar == '[');
                        if (typeChar == 'L') {
                            // Skip the class name of the array component type
                            do {
                                typeChar = parameters.charAt(i++);
                            } while (typeChar != ';');
                        }
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid type descriptor: " + typeChar);
                }
            }
        } else {
            // Single type descriptor
            switch (descriptor.charAt(0)) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'J': // long
                case 'S': // short
                case 'Z': // boolean
                case 'L': // object reference
                    // Pop a single type from the stack
                    break;
                case '[': // array
                    // Pop an array from the stack
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type descriptor: " + descriptor.charAt(0));
            }
        }
    } catch (Exception e) {
        // Handle any exceptions that may occur
        e.printStackTrace();
    }
}

