String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    int i = 0;
    while (i < len) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (++i >= len) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char nextChar = str.charAt(i);
            switch (nextChar) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= len) {
                        throw new Exception("Invalid unicode escape sequence at end of string");
                    }
                    String unicode = str.substring(i + 1, i + 5);
                    try {
                        sb.append((char) Integer.parseInt(unicode, 16));
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape sequence: " + unicode);
                    }
                    i += 4;
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
            }
        } else {
            sb.append(c);
        }
        i++;
    }
    return sb.toString();
}

