protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    try {
        List<E> edgeList = new ArrayList<>(tour);
        V startVertex = edgeList.isEmpty() ? null : graph.getEdgeSource(edgeList.get(0));
        List<V> vertexPath = new ArrayList<>();
        Set<E> visitedEdges = new HashSet<>();

        V currentVertex = startVertex;
        while (currentVertex != null && !visitedEdges.containsAll(tour)) {
            vertexPath.add(currentVertex);
            E nextEdge = edgeList.stream()
                .filter(e -> graph.getEdgeSource(e).equals(currentVertex) || graph.getEdgeTarget(e).equals(currentVertex))
                .filter(e -> !visitedEdges.contains(e))
                .findFirst().orElse(null);
            if (nextEdge != null) {
                visitedEdges.add(nextEdge);
                currentVertex = graph.getEdgeSource(nextEdge).equals(currentVertex) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
            } else {
                currentVertex = null; // Stuck, no path possible
            }
        }

        // Close the tour if it's not already closed
        if (!vertexPath.isEmpty() && !vertexPath.get(0).equals(currentVertex)) {
            vertexPath.add(startVertex);
        }

        return graph.getPath(vertexPath);
    } catch (Exception e) {
        // Handle exceptions as appropriate, e.g., return null or throw a custom exception
        return null;
    }
}

