private int popType(final String descriptor, int index) {
    char ch = descriptor.charAt(index);
    switch (ch) {
        case 'B':
        case 'C':
        case 'D':
        case 'F':
        case 'I':
        case 'J':
        case 'S':
        case 'Z':
        case 'V':
            index++; // Simple types are one character long
            break;
        case 'L':
            // Object type, skip until ';'
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            index++; // Skip the ';'
            break;
        case '[':
            // Array type, skip all '[' and then the type
            while (descriptor.charAt(index) == '[') {
                index++;
            }
