    try {
        if (this.nodeIterator == null || !this.nodeIterator.hasNext()) {
            throw new IllegalStateException("No next node available.");
        }
        Node current = this.currentNode;
        Node next = this.nodeIterator.next();
        for (Edge edge : this._edges) {
            if ((edge.getFrom() == current && edge.getTo() == next) ||
                (edge.getFrom() instanceof VirtualNode && ((VirtualNode) edge.getFrom()).getRealNode() == current && edge.getTo() == next) ||
                (edge.getTo() instanceof VirtualNode && ((VirtualNode) edge.getTo()).getRealNode() == next && edge.getFrom() == current)) {
                return edge;
            }
        }
        throw new NoSuchElementException("No edge found between current node and next node.");
    } catch (Exception e) {
